    if (req.method === 'POST' && req.url === '/__switch/api/kk/keepalive/config') return keepaliveKk.config(req, res);
    if (req.method === 'POST' && req.url === '/__switch/api/fx/keepalive/config') return keepaliveFx.config(req, res);
