    if (req.method === 'GET'  && req.url.startsWith('/__switch/api/go/sessions')) return handleGoSessions(req, res);
    if (req.method === 'GET'  && req.url.startsWith('/__switch/api/go/ping'))     return handleGoPing(req, res);
