    if (req.method === 'GET'  && req.url === '/__switch/api/go/modelmap') return jsonRes(res, 200, { ok: true, modelMap: goReadModelMap() });
    if (req.method === 'POST' && req.url === '/__switch/api/go/add')       return handleGoAdd(req, res);
